import personalidad_datos_en as D  # noqa: E402


def reemplazar(s, pares, nombre):
    for es, en in pares:
        if es not in s:
            raise SystemExit(f'{nombre}: no encuentro «{es[:80]}»')
        s = s.replace(es, en)
    return s


# ---------------------------------------------------------------- datos
B = json.loads(subprocess.run(['node', '-e', "global.window={};require(process.argv[1]);process.stdout.write(JSON.stringify(window.BIG5))", os.path.join(ES, 'datos.js')],
                              capture_output=True, text=True, check=True).stdout)
assert len(B['I50']) == len(D.I50) == 50 and len(B['I120']) == len(D.I120) == 120
B['I50'] = [[x[0], x[1], t] for x, t in zip(B['I50'], D.I50)]
B['I120'] = [[x[0], x[1], x[2], t] for x, t in zip(B['I120'], D.I120)]
B['FACETAS'], B['FACETAS_DESC'] = D.FACETAS, D.FACETAS_DESC
for k, r in D.RASGOS.items():
    base = B['RASGOS'][k]
    libros = [[ref, t] for (ref, _), t in zip(base['libros'], r['libros'])]
    base.update({x: y for x, y in r.items() if x != 'libros'}); base['libros'] = libros
for k, p in D.PERFILES.items():
    B['PERFILES'][k].update(p)
