H = H.replace('>Privacy</a>', f'>Privacy</a> · <a href="{URL_ES}" hreflang="es" lang="es">Versión en español</a>', 1)
cuerpo = re.sub(r'<script.*?</script>|<style.*?</style>', '', H[H.find('<body'):], flags=re.S)
restos = [t.strip() for t in re.findall(r'>([^<>]*[áéíóúñ¿¡][^<>]*)<', cuerpo) if t.strip() and 'Versión en español' not in t]
if restos: raise SystemExit('index.html: quedan textos en español: ' + ' | '.join(restos[:10]))

